import React, { memo } from 'react';
import MessageDialog from '@baifendian/adhere-ui-messagedialog';
import Intl from '@baifendian/adhere-util-intl';
import Resource from '@baifendian/adhere-util-resource';
const selectorPrefix = 'adhere-ui-del-confirm';
/**
 * DelConform
 * @param props
 * @constructor
 */
const InternalDelConform = memo((props) => {
    const { className, style, children } = props;
    function onClick(e) {
        e.stopPropagation();
        const { children, ...params } = props;
        DelConform.open({ ...params });
    }
    return (React.createElement("div", { className: `${selectorPrefix} ${className ?? ''}`, style: style ?? {}, onClick: onClick }, children));
});
const DelConform = InternalDelConform;
DelConform.displayName = 'DelConform';
DelConform.open = ({ success, ...params }) => {
    MessageDialog.Confirm({
        ...params,
        title: params.title || Intl.v('提示'),
        text: params.text || `${Intl.v('确定删除吗')}?`,
        zIndex: 'zIndex' in params ? params.zIndex : Resource?.Dict?.value?.ResourceNormalMaxZIndex?.value,
        onSuccess: () => new Promise((resolve, reject) => {
            if (success) {
                success()
                    .then(() => resolve())
                    .catch(() => reject());
            }
            else {
                resolve();
            }
        }),
    });
};
export default DelConform;
